const chapters=['The first few edits','Move with intention','Speak in text objects','Lines, meet operators','Search & repeat','The power tools'];
const missions=[];
function mission(ch,title,instruction,before,after,cursor,keys,concept,hint,why){missions.push({ch,title,instruction,before,after,cursor,keys,concept,hint,why})}
mission(0,'One character too many.','Delete the extra “p” in “appple”.','appple juice\norange juice\nlemon tea','apple juice\norange juice\nlemon tea',[0,2],['x'],'x · delete a character','You’re already on the extra letter. In Normal mode, x deletes the character under the cursor.','x makes a tiny deletion without leaving Normal mode. No selection, no backspace, no mode switch.');
mission(0,'A small change of plans.','Change “cat” to “bat”.','cat naps in the sun','bat naps in the sun',[0,0],['r','b'],'r · replace a character','Press r, then the replacement letter.','r replaces exactly one character and returns straight to Normal mode.');
mission(0,'Make an entrance.','Add “hello ” before “world”.','world','hello world',[0,0],['i',...'hello ','<Esc>'],'i · insert before cursor','i enters Insert mode. Type hello followed by a space, then Escape.','i inserts before the cursor. Escape brings you back to Normal mode, ready for your next command.');
mission(0,'The finishing touch.','Add an exclamation mark at the end.','hello, world','hello, world!',[0,0],['A','!','<Esc>'],'A · append to line','Capital A moves to the end of the line and enters Insert mode.','A combines a motion and a mode switch. Use it when you already know the edit belongs at the end.');
mission(0,'A fresh line.','Add “water the plants” below the first task.','make coffee\nstart work','make coffee\nwater the plants\nstart work',[0,0],['o',...'water the plants','<Esc>'],'o · open a line below','Lowercase o opens a new line below the current one.','o creates the line and puts you in Insert mode in one move.');
mission(1,'Skip the scenic route.','Remove the word “very ”.','a very good morning','a good morning',[0,0],['w','d','w'],'w · move by words','w jumps to the next word. Then dw deletes a word and its following space.','Think “next word, delete word.” Word motions beat tapping the arrow keys.');
mission(1,'Three words, one move.','Remove “one two three ”, leaving “go!”.','one two three go!','go!',[0,0],['d','3','w'],'counts · multiply a motion','A count can go between an operator and its motion: d3w.','d3w means delete across three word motions. Counts let a single instruction cover a larger distance.');
mission(1,'Find your mark.','Replace the first comma with a colon.','name, email, city','name: email, city',[0,0],['f',',','r',':'],'f · find a character','f followed by a character finds its next occurrence on the same line.','f, lands directly on the comma. rb would replace it with b; here r: makes it a colon.');
mission(1,'Keep the good part.','Remove everything from the cursor to the end of the line.','keep this // remove this','keep this ',[0,10],['D'],'D · delete to end','Capital D deletes from the cursor through the end of the line. Keep the space before the cursor.','D is the compact form of d$. Both express the same edit: delete to the end.');
mission(1,'Start with a comment.','Add “# ” at the beginning of the line.','ship it today','# ship it today',[0,8],['I','#',' ','<Esc>'],'I · insert at line start','Capital I starts inserting at the first nonblank character.','I takes you to the start of the content, regardless of where you were on the line.');
mission(2,'Change the word, not the sentence.','Replace “cold” with “hot”.','a cold cup of coffee','a hot cup of coffee',[0,4],['c','i','w','h','o','t','<Esc>'],'ciw · change inner word','ciw changes the word you’re inside, even if you aren’t on its first letter.','Operator + text object: c means change, iw means inner word. The cursor can be anywhere inside the word.');
mission(2,'Inside the quotes.','Replace the quoted text with “hello”.','message = "good morning"','message = "hello"',[0,13],['c','i','"',...'hello','<Esc>'],'ci" · change inside quotes','ci" changes everything inside the quotes while keeping the quotes.','Text objects describe what to edit. ci" saves you from counting characters or locating both ends.');
mission(2,'An empty invitation.','Remove the arguments, keeping the parentheses.','invite(alex, sam, jo)','invite()',[0,9],['d','i','('],'di( · delete inside parentheses','di( deletes inside the surrounding parentheses.','The inner object keeps its delimiters. The same pattern works with brackets and braces.');
mission(2,'Take the wrapper, too.','Remove “(optional)” and leave the two surrounding spaces.','name (optional) here','name  here',[0,9],['d','a','('],'da( · delete around parentheses','Use a instead of i to include the parentheses: da(.','Inner objects keep the wrapper; around objects include it. Spaces outside these parentheses remain untouched.');
mission(2,'A better list.','Replace the contents of the brackets with “red, blue”.','colors = [gray, gray, gray]','colors = [red, blue]',[0,14],['c','i','[',...'red, blue','<Esc>'],'ci[ · change inside brackets','ci[ changes the contents of the surrounding square brackets.','Once you know the operator + object grammar, the same idea transfers to a different delimiter.');
mission(3,'Clear the noise.','Delete the entire “DEBUG: temporary” line.','ready\nDEBUG: temporary\nset\ngo','ready\nset\ngo',[1,0],['d','d'],'dd · delete a line','Double an operator to apply it to the whole line. Try dd.','dd removes the line and its line break. The deleted line is also available to paste.');
mission(3,'One more chorus.','Duplicate the “la la la” line below itself.','verse\nla la la\noutro','verse\nla la la\nla la la\noutro',[1,0],['y','y','p'],'yy + p · copy and paste','yy copies the current line. p puts it below.','Yank is Vim’s word for copy. Linewise yanks paste as complete lines.');
mission(3,'Put things in order.','Move “second” below “first”.','second\nfirst\nthird','first\nsecond\nthird',[0,0],['d','d','p'],'dd + p · move a line','dd cuts the line. After it disappears, p puts it below the current line.','Delete and put compose into a move. You don’t need a separate cut command.');
mission(3,'Bring it together.','Join the two lines with a space.','hello,\nworld!','hello, world!',[0,0],['J'],'J · join lines','Capital J joins the current line with the next.','J handles the line break and inserts a separating space for you.');
mission(3,'A clean slate.','Replace the whole line with “done”.','this entire line can go','done',[0,7],['c','c',...'done','<Esc>'],'cc · change a line','cc changes the current line, no matter where the cursor is.','Like dd and yy, cc acts on a full line. It then enters Insert mode.');
mission(4,'Go straight there.','Change “blue” to “green”.','red orange yellow blue violet','red orange yellow green violet',[0,0],['/',...'blue','<Enter>','c','i','w',...'green','<Esc>'],'/ · search','Type /blue and Enter to find the word, then ciw to change it.','Search is a motion tool. Jump to something you can name rather than counting the distance.');
mission(4,'Do that again.','Change both “cold” words to “warm”.','cold tea, cold toast','warm tea, warm toast',[0,0],['c','i','w',...'warm','<Esc>','W','W','.'],'. · repeat the last change','Change the first word with ciw. Move to the other cold with WW, then press dot.','The dot command repeats your last change, including the inserted text. Make one useful change, then reuse it.');
mission(4,'Follow the word.','Change only the second “cat” to “dog”.','cat and cat','cat and dog',[0,0],['*','c','i','w',...'dog','<Esc>'],'* · find this word again','* finds the next occurrence of the word under the cursor.','* turns the current word into a search. n continues forward through matches.');
mission(4,'A clean sweep.','Replace every “red” with “blue” on all three lines.','red kite\nred boat\nred bike','blue kite\nblue boat\nblue bike',[0,0],[':',...'%s/red/blue/g','<Enter>'],':%s · substitute everywhere','Type :%s/red/blue/g then Enter. % means every line; g means every match per line.','Substitution is ideal when the same textual replacement applies throughout a file.');
mission(4,'Up to the fence.','Delete “remove me” but keep the semicolon.','remove me;keep me',';keep me',[0,0],['d','t',';'],'dt · delete until a character','dt; deletes up to, but not including, the semicolon.','t stops just before a character. Pair it with d to express a precise boundary without counting.');
mission(5,'Make it loud.','Uppercase the word “quiet”.','a quiet room','a QUIET room',[0,3],['g','U','i','w'],'gU · uppercase an object','gU is an uppercase operator. Add iw to apply it to the current word.','Operators do more than delete and change. gUiw uses the same text-object grammar to transform case.');
mission(5,'Select with purpose.','Delete the first two lines, leaving only “shoes”.','shirts\nsocks\nshoes','shoes',[0,0],['V','j','d'],'V · select whole lines','V selects a line; j extends to the next. d deletes the selection.','Visual line mode makes a multi-line selection explicit. Operators act on what you select.');
mission(5,'A register to remember.','Copy “reusable” into register a, then paste it after “finish”.','reusable\nfinish','reusable\nfinish\nreusable',[0,0],['"','a','y','y','j','"','a','p'],'"a · named register','"ayy yanks into register a. Move down with j, then "ap puts it.','Named registers keep reusable text separate from the default register. The target checks text; try the register sequence to practice the technique.');
mission(5,'Teach Vim a little routine.','Add “- ” to the beginning of all three lines.','apples\npears\nplums','- apples\n- pears\n- plums',[0,0],['q','a','I','-',' ','<Esc>','j','q','2','@','a'],'q + @ · record and replay','qa starts recording into a. I adds a prefix, Escape then j moves down. q stops; 2@a replays twice.','A macro records a sequence of actions. End each recording where the next repetition should begin.');
mission(5,'The final field test.','Change both quoted values to “ready”.','state = "waiting"\nnext = "pending"','state = "ready"\nnext = "ready"',[0,10],['c','i','"',...'ready','<Esc>','j','.'],'compose · text objects + repeat','Change inside the first quotes, move down with j, and repeat with dot.','A well-shaped change is reusable. Text objects and dot work together even when the old values have different lengths.');

// Deliberate practice: each drill varies an editing boundary, scope, or composition.
// These are authored tasks, not randomized word substitutions.
function drill(topic,title,before,after,cursor,keys,hint,why){mission(topic,title,title,before,after,cursor,keys,topic,hint,why)}

// Precision repairs: avoid entering Insert mode for every correction.
drill('Character repairs','Change “&” to “and”.','Bread & butter','Bread and butter',[0,6],['s',...'and','<Esc>'],'s replaces the character under the cursor and enters Insert mode.','s combines deleting one character with starting an insertion. Unlike r, it lets you replace one character with several.');
drill('Character repairs','Remove the extra slash before “images”.','assets//images/logo.svg','assets/images/logo.svg',[0,8],['X'],'The cursor is on i. Capital X deletes the character immediately before it.','Use X when the unwanted character is behind the cursor. There is no need to move left first.');
drill('Character repairs','Fix “teh” to read “the”.','Read teh manual.','Read the manual.',[0,6],['x','p'],'Delete the e with x, then put it after the h with p.','Deleting a character stores it in a register. xp puts it after the next character, swapping adjacent letters.');
drill('Character repairs','Capitalize the first letter of “paris”.','Destination: paris','Destination: Paris',[0,13],['~'],'The tilde key toggles the case of the character under the cursor.','~ changes the existing letter without asking you to retype it. It is useful for one-letter capitalization fixes.');
drill('Case','Make “WARNING” lowercase.','level = WARNING','level = warning',[0,11],['g','u','i','w'],'gu is the lowercase operator; iw selects the current word.','guiw lowercases a whole word from anywhere inside it. The surrounding assignment stays untouched.');
drill('Case','Make the entire email address lowercase.','SUPPORT@EXAMPLE.COM','support@example.com',[0,8],['g','u','u'],'guu lowercases the current line.','A linewise case operation includes punctuation-separated parts such as an email address. It avoids treating each part as a separate word.');

// word versus WORD, whitespace ownership, and partial-word edits.
drill('Word boundaries','Replace the file path with “src/app.ts”.','open old/lib/main.js now','open src/app.ts now',[0,12],['c','i','W',...'src/app.ts','<Esc>'],'Capital W treats the entire non-space path as one WORD. Use ciW.','iw stops at punctuation; iW includes slashes and dots. Choose the object that matches the whole value you want to replace.');
drill('Word boundaries','Remove the “--verbose” flag.','build --verbose --release','build --release',[0,10],['d','a','W'],'daW removes the whitespace-delimited WORD and its following space.','The around-WORD object includes the hyphens and the separating space. The remaining command keeps exactly one space.');
drill('Word boundaries','Remove “temporary” from the comment.','// temporary workaround for Safari','// workaround for Safari',[0,7],['d','a','w'],'daw deletes the word you are inside and one adjacent space.','daw is useful for removing a word from prose without leaving doubled spaces. The cursor does not have to be at the start.');
drill('Word boundaries','Replace “guest ” with “admin ”.','grant guest access','grant admin access',[0,8],['c','a','w',...'admin ','<Esc>'],'caw replaces the word and its following space. Include a space after admin.','An around-word change consumes a separator. Retype that separator when you want the following word to stay separate.');
drill('Word boundaries','Rename “count” to “total”, keeping the comma.','send(count, limit);','send(total, limit);',[0,5],['c','w',...'total','<Esc>'],'At the start of count, cw changes the word without consuming the comma.','For a word under the cursor, cw changes through its end. Punctuation makes a useful boundary for a small rename.');
drill('Word boundaries','Change the suffix “Name” to “Id”.','userName = value','userId = value',[0,4],['c','e','I','d','<Esc>'],'The cursor is on N. ce changes from here to the end of the word.','ce can replace just a suffix. ciw would replace the entire identifier, including the user prefix.');

// Line edges and line creation from deliberately inconvenient cursor positions.
drill('Line boundaries','Add “# Release notes” above the list.','- Fix login\n- Improve search','# Release notes\n- Fix login\n- Improve search',[0,7],['O',...'# Release notes','<Esc>'],'Capital O opens a new line above the current one.','O adds a line above without moving to column one or disturbing the existing line.');
drill('Line boundaries','Comment out the indented “return” line.','if (ready) {\n  return result;\n}','if (ready) {\n  // return result;\n}',[1,10],['I',... '// ','<Esc>'],'I inserts before the first nonblank character, preserving the two-space indentation.','I targets the start of the content, not column zero. That distinction keeps an indented comment aligned with its block.');
drill('Line boundaries','Remove “DEBUG ” from the start of the message.','DEBUG server listening','server listening',[0,15],['0','d','w'],'0 moves to column zero. Then dw removes the first word and its space.','A known line boundary is more reliable than counting backward. 0 also works when you start deep inside the line.');
drill('Line boundaries','Change the destination to “production”.','deploy to staging now','deploy to production',[0,10],['C',...'production','<Esc>'],'The cursor is on staging. C changes everything from here to the line end.','C replaces an entire tail, including several words. It is the change counterpart of D.');
drill('Line ranges','Delete the three consecutive DEBUG lines.','ready\nDEBUG connect\nDEBUG retry\nDEBUG trace\ncomplete','ready\ncomplete',[1,0],['3','d','d'],'3dd deletes three whole lines starting at the cursor.','A count on dd describes a known-size block. Each line break goes with its line.');
drill('Line ranges','Delete the temporary notes at the end.','title: Release\nstatus: ready\nTEMP notes\nremove this\nand this','title: Release\nstatus: ready',[2,0],[':',...'3,$d','<Enter>'],'Use :3,$d to delete from line 3 through the last line.','In an Ex range, $ means the last line. The endpoint follows the buffer length, so the command also works with a longer footer.');

// Whole-buffer motions, joins, and block movement.
drill('Line ranges','Remove the two-line banner above the settings.','# Generated file\n# Do not edit\nport = 8080\nhost = localhost','port = 8080\nhost = localhost',[1,5],['d','g','g'],'dgg deletes the current line and all lines above it.','gg points to the start of the buffer. With d, the motion removes the full header without counting its characters.');
drill('Joining','Join the three-line sentence into one line.','Ship small changes\nand keep the\nfeedback loop short.','Ship small changes and keep the feedback loop short.',[0,4],['3','J'],'3J joins three lines with spaces.','A count on J is the total number of lines to join. It preserves word separation at each boundary.');
drill('Joining','Join the path without adding a space.','/usr/local/\nbin/tool','/usr/local/bin/tool',[0,0],['g','J'],'gJ joins with the next line without inserting a space.','J is right for prose; gJ is right when adjacent pieces must touch, such as a split path or identifier.');
drill('Moving lines','Move “install” above “test”.','prepare\ntest\ninstall\ndeploy','prepare\ninstall\ntest\ndeploy',[2,0],['d','d','k','P'],'Cut install with dd, move up to test with k, and put above it with P.','Lowercase p puts a line below; uppercase P puts it above. This makes the insertion side explicit.');
drill('Copying blocks','Copy both default settings below “[local]”.','[defaults]\nretries = 3\ntimeout = 10\n[local]','[defaults]\nretries = 3\ntimeout = 10\n[local]\nretries = 3\ntimeout = 10',[1,0],['2','y','y','G','p'],'2yy copies two lines. G moves to the bottom; p puts the block below it.','Linewise yanks preserve the block’s line breaks. One put inserts both settings together.');
drill('Copying text','Copy “customer_id” into the empty argument list.','customer_id\nlookup()','customer_id\nlookup(customer_id)',[0,4],['y','i','w','j','f','(','p'],'yiw copies the identifier. On the next line, f( finds the opening parenthesis; p puts after it.','A characterwise yank fits inside an existing line. This combines an object for copying with a character search for placement.');

// Registers and navigation: preserve text while moving and deleting.
drill('Copying text','Copy the quoted filename after “backup: ”.','source: "config.yml"\nbackup:','source: "config.yml"\nbackup: config.yml',[0,12],['y','i','"','j','A',' ','<Esc>','p'],'yi" copies only the filename. Move down, append a space with A, Escape, then p.','Yanking inside quotes excludes the delimiters. The copied content can be reused in a different format.');
drill('Registers','Delete the TODO line and fill in “token: api_key”.','api_key\nTODO remove\ntoken:','api_key\ntoken: api_key',[0,3],['y','i','w','j','d','d','$','a',' ','<Esc>','"','0','p'],'Yank api_key, delete the TODO line, then append a space and put register zero with "0p.','Register 0 retains the last yank even after a deletion replaces the unnamed register. It keeps the copied identifier available.');
drill('Registers','Delete “obsolete” and copy “template” below “final”.','template\nobsolete\nfinal','template\nfinal\ntemplate',[0,0],['y','y','j','"','_','d','d','p'],'yy copies template. j"_dd deletes obsolete into the black-hole register; p still puts template.','The black-hole register discards a deletion without replacing your copied text. The result accepts any route; this route practices preserving a yank.');
drill('Marks','Move the release note directly below the heading.','# Plan\n- build\n- test\nNote: ship Friday\n---','# Plan\nNote: ship Friday\n- build\n- test\n---',[0,0],['m','a','G','k','d','d',"'",'a','p'],'ma marks the heading. Gkdd cuts the note above the final separator. Apostrophe-a returns to the marked line; p puts below.','A mark remembers a destination while you fetch text elsewhere. Apostrophe returns to the start of that marked line.');
drill('Character search','Add “.trim()” after the closing parenthesis.','read(input);','read(input).trim();',[0,0],['f',')','a',...'.trim()','<Esc>'],'f) lands on the closing parenthesis. a inserts immediately after it.','Find the delimiter, then choose which side to insert on. This is more direct than counting the argument’s length.');
drill('Character search','Change only the second comma to a semicolon.','name,email,role,active','name,email;role,active',[0,0],['2','f',',','r',';'],'2f, finds the second comma. r; replaces that one character.','A count can select the second occurrence of a delimiter. Other separators stay unchanged.');

// Finding boundaries forward and backward; composing find with operators.
drill('Character search','Change the colon after “port” to “=”.','server:port:8080','server:port=8080',[0,14],['F',':','r','='],'Capital F searches backward on the current line. F: finds the nearest colon to the left.','Backward character search is useful when the cursor has already passed the edit. Lowercase f would look in the wrong direction.');
drill('Character search','Remove the label, keeping the quoted message.','message: "ready"','"ready"',[0,0],['d','t','"'],'dt" deletes up to, but not including, the opening quote.','t excludes the delimiter. That lets you strip a prefix while keeping the quoted value intact.');
drill('Character search','Change the first CSV field to “Mina”.','Alex,design,remote','Mina,design,remote',[0,0],['c','t',',',...'Mina','<Esc>'],'ct, changes up to the next comma, keeping the comma.','A delimiter is a better boundary than a word when a field may contain spaces. This change preserves the rest of the row.');
drill('Character search','Remove “https:” from the URL.','https://example.com/docs','//example.com/docs',[0,0],['d','f',':'],'df: deletes through the colon, including it.','f includes the found character when used with d. Compare that with dt:, which would leave the colon behind.');
drill('Character search','Change the second colon to “=”.','cache:ttl:60','cache:ttl=60',[0,0],['f',':',';','r','='],'f: finds the first colon; semicolon repeats that find. Then r= replaces it.','The semicolon repeats the last character search. It is useful when you discover the right occurrence by moving through delimiters.');
drill('Matching pairs','Change the outer parentheses into brackets.','(first, second)','[first, second]',[0,0],['%','r',']','0','r','['],'% jumps from the opening parenthesis to its match. Replace the closing one, then return to column zero.','% follows a matching pair. It avoids counting across the enclosed text, and is especially useful with longer expressions.');

// Structured values: preserve wrappers, choose the correct nesting level.
drill('Text objects','Change the single-quoted value to “production”.',"env = 'development'","env = 'production'",[0,11],['c','i',"'",...'production','<Esc>'],"ci' changes only the text inside single quotes.",'The text object follows the delimiter you name. The assignment and quotes remain unchanged.');
drill('Text objects','Replace the template string with “Hello, team”.','message = `Welcome back`','message = `Hello, team`',[0,15],['c','i','`',...'Hello, team','<Esc>'],'ci` changes the contents of the backticks.','You can use a quoted text object for a whole phrase. There is no need to delete its words individually.');
drill('Text objects','Replace the object contents with “enabled: true”.','options = {debug: true, retries: 2};','options = {enabled: true};',[0,16],['c','i','{',...'enabled: true','<Esc>'],'ci{ changes inside the braces while keeping the braces and semicolon.','The brace object treats the configuration body as one region, independent of punctuation and spacing inside it.');
drill('HTML objects','Change the link label to “Read the guide”.','<a href="/guide">Click here</a>','<a href="/guide">Read the guide</a>',[0,19],['c','i','t',...'Read the guide','<Esc>'],'cit changes the text inside the surrounding tag.','The inner-tag object preserves the element and its attributes. You can change a label without rewriting its URL.');
drill('HTML objects','Remove the “Sold out” badge, keeping the paragraph.','<span>Sold out</span><p>Details</p>','<p>Details</p>',[0,9],['d','a','t'],'dat deletes the surrounding element, including its opening and closing tags.','Around-tag includes the wrapper. This is different from dit, which would leave an empty span behind.');
drill('Nested objects','Empty “format()”, keeping “log()” and its other argument.','log(format(customer), level);','log(format(), level);',[0,14],['d','i','('],'di( targets the nearest surrounding pair: the format arguments.','Nested objects let you choose a local region by cursor placement. The outer call and its other argument are preserved.');

// Search and substitute: teach scope, not blanket replacement.
drill('Search','Replace the FIXME comment with “// handled upstream”.','function run() {\n  start();\n  // FIXME: remove workaround\n  finish();\n}','function run() {\n  start();\n  // handled upstream\n  finish();\n}',[0,0],['/',...'FIXME','<Enter>','c','c',...'// handled upstream','<Esc>'],'Search for FIXME, press Enter, then cc changes its line while keeping indentation.','Search can find an editing location without knowing its line number. cc keeps the indentation of the line you found.');
drill('Search','Mark only the second TODO as DONE.','// TODO: add tests\n// TODO: update docs\n// TODO: benchmark','// TODO: add tests\n// DONE: update docs\n// TODO: benchmark',[0,0],['/',...'TODO','<Enter>','n','c','i','w',...'DONE','<Esc>'],'/TODO finds the first match. n goes to the second; ciw replaces just that word.','Separate navigation from the change. n advances through search matches without replacing any of them.');
drill('Search','Change the earlier “draft” to “ready”.','draft proposal\ndraft appendix','ready proposal\ndraft appendix',[1,0],['#','c','i','w',...'ready','<Esc>'],'# searches backward for the word under the cursor. Then ciw changes the earlier occurrence.','The backward counterpart of * is #. It is handy when the relevant occurrence is above your current position.');
drill('Substitution','Change “http” to “https” on the current line only.','url = http://example.com\nlegacy = http://archive.test','url = https://example.com\nlegacy = http://archive.test',[0,0],[':',...'s/http/https/','<Enter>'],'Use :s/http/https/ with no range. It applies only to the current line.','Omitting % keeps the substitution local. Scope is part of the command, not just the replacement text.');
drill('Substitution','Change “off” to “on” on lines 2 and 3 only.','global = off\nsearch = off\nexport = off\nlegacy = off','global = off\nsearch = on\nexport = on\nlegacy = off',[0,0],[':',...'2,3s/off/on/','<Enter>'],'The range 2,3 limits substitution to those two lines.','A numeric range protects matching text outside the intended block. The global and legacy settings stay off.');
drill('Substitution','Rename only the first “old” on each line to “new”.','old -> old\nold => old','new -> old\nnew => old',[0,0],[':',...'%s/old/new/','<Enter>'],'Use :%s/old/new/ without the g flag.','% includes every line; omitting g changes only the first match on each line. The right-hand values remain old.');

// Scoped bulk cleanup, indentation, and numeric editing.
drill('Substitution','Rename standalone “id” to “key”, keeping “user_id”.','id = user_id\nprint(id)','key = user_id\nprint(key)',[0,0],['*','N','c','i','w',...'key','<Esc>','n','.'],'* searches for the whole word id. N returns to the first occurrence; change it with ciw, then n and dot change the next.','The whole-word search created by * skips user_id. Repeating the change at search matches keeps longer identifiers intact.');
drill('Global commands','Remove every line that starts with “DEBUG”.','INFO boot\nDEBUG cache\nINFO ready\nDEBUG trace\nERROR timeout','INFO boot\nINFO ready\nERROR timeout',[0,0],[':',...'g/^DEBUG/d','<Enter>'],'Use :g/^DEBUG/d. The caret anchors the match to the start of a line.','The global command runs d on matching lines. This filters scattered log lines without manually finding each one.');
drill('Indentation','Indent “send();” by two spaces.','if (ready) {\nsend();\n}','if (ready) {\n  send();\n}',[1,0],['>','>'],'>> shifts the current line right by one indentation level. This editor uses two spaces.','A shift operator changes indentation without entering Insert mode. It leaves the code itself untouched.');
drill('Indentation','Remove one indentation level from “return value;”.','function read() {\n    return value;\n}','function read() {\n  return value;\n}',[1,7],['<','<'],'<< shifts the current line left by two spaces.','Shifting applies to the line even when the cursor is in its middle. You do not have to move into the leading whitespace.');
drill('Indentation','Indent both statements inside the block by two spaces.','if (ready) {\nload();\nsend();\n}','if (ready) {\n  load();\n  send();\n}',[1,0],['V','j','>'],'V selects the current line, j includes the next, and > indents both.','Visual line selection makes the scope visible before a block operation. The closing brace is deliberately excluded.');
drill('Numbers','Increase the retry count from 3 to 4.','retries = 3','retries = 4',[0,10],['<C-a>'],'Ctrl+a increments the number under the cursor.','Numeric editing changes the value without replacing its digits manually. It also works across digit boundaries.');

// Repetition: repeat a useful change, then compose a reusable macro.
drill('Numbers','Decrease the timeout from 100 to 99.','timeout = 100','timeout = 99',[0,10],['<C-x>'],'Ctrl+x decrements the number under the cursor.','Decrement handles borrowing and a change in digit count. You do not need to replace the whole number.');
